from decimal import Decimal
from typing import Any


def _number(value: Any) -> Decimal:
    """Apply legacy NVL/numeric coercion semantics."""
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        if value.strip() == "":
            return Decimal(0)
        return Decimal(value)
    return Decimal(str(value))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Run the legacy credit-hold sweep without mutating input rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    live_customer_indices = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y"
        and account.get("ACCT_TYP") == "C"
    ]

    # CRMScript FOR EACH iteration is by primary key ascending.
    live_customer_indices.sort(key=lambda index: accounts[index].get("ACCT_ID"))

    for index in live_customer_indices:
        account = accounts[index]
        acct_id = account.get("ACCT_ID")

        exposure = Decimal(0)
        for order in orders:
            if (
                order.get("DEL_FLG") != "Y"
                and order.get("ACCT_ID") == acct_id
                and order.get("STAT_CD") == "I"
            ):
                exposure += _number(order.get("TOT_AMT"))

        credit_limit = _number(account.get("CRED_LIMIT"))
        current_hold = account.get("CRED_HOLD")

        if exposure > credit_limit and current_hold != "Y":
            new_accounts[index]["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        # This is intentionally evaluated after the hold-on IF.
        current_hold = new_accounts[index].get("CRED_HOLD")
        if exposure <= (credit_limit * Decimal(8) / Decimal(10)) and current_hold == "Y":
            new_accounts[index]["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
